<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';$id=(int)($_GET['id']??0);$a=mp550_auction($id);if(!$a){http_response_code(404);exit('Auction not found.');}$me=current_user();$flash='';$err='';if(($_SERVER['REQUEST_METHOD']??'')==='POST'){if(!$me){header('Location: /login.php');exit;}csrf_check();try{$action=(string)($_POST['action']??'bid');if($action==='bid'){$r=mp550_place_bid($id,(int)$me['id'],(float)$_POST['max_bid']);$flash=$r['extended']?'Bid placed. Auction time was extended by anti-sniping protection.':'Bid placed. Automatic bidding is active up to your maximum.';}elseif($action==='watch'){db()->prepare('INSERT IGNORE INTO marketplace_auction_watchers_v550(auction_id,user_id,created_at) VALUES(?,?,NOW())')->execute([$id,(int)$me['id']]);$flash='Auction added to your watchlist.';}elseif($action==='winner_checkout'){if(trim((string)($_POST['address']??''))==='')throw new RuntimeException('Delivery address is required.');$oid=mp550_checkout_auction($id,(int)$me['id'],['name'=>$me['name'],'phone'=>$me['phone']??'','email'=>$me['email']??'','address'=>$_POST['address']],(string)($_POST['payment_method']??'cod'));header('Location: /my-orders.php?id='.$oid);exit;}}catch(Throwable $e){$err=$e->getMessage();}$a=mp550_auction($id);}mp550_public_header($a['title'].' Auction');$min=max((float)$a['start_price'],(float)$a['current_price']+(float)$a['min_increment']);
?>
<?php if($flash):?><div class="mp550-alert ok top"><?=e($flash)?></div><?php endif;?><?php if($err):?><div class="mp550-alert err top"><?=e($err)?></div><?php endif;?><section class="auction-page"><div class="auction-photo"<?=!empty($a['image_url'])?' style="background-image:url(\''.e($a['image_url']).'\')"':''?>><span class="status <?=e($a['status'])?>"><?=e(strtoupper($a['status']))?></span></div><div class="auction-bidbox"><small><?=e($a['shop_name']?:$a['seller_name'])?></small><h1><?=e($a['title'])?></h1><p><?=e((string)$a['short_description'])?></p><div class="auction-current"><span>Current bid</span><b><?=mp550_money((float)$a['current_price'])?></b><small>Minimum increment <?=mp550_money((float)$a['min_increment'])?></small></div><div class="auction-clock"><span>Time remaining</span><b data-countdown="<?=e($a['ends_at'])?>"></b><small>Anti-sniping: <?=(int)$a['anti_snipe_seconds']?> sec · max <?=(int)$a['max_extensions']?> extensions</small></div><?php if($a['status']==='live'):?><form method="post" class="bid-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="bid"><label>Your maximum automatic bid<input type="number" step="1" min="<?=e((string)$min)?>" name="max_bid" required placeholder="<?=e((string)$min)?>"></label><button class="mp550-btn wide">Place secure bid</button><small>Your maximum is private. The system only raises your effective bid when another bidder challenges you.</small></form><?php elseif($a['status']==='ended'&&$me&&(int)$a['winner_user_id']===(int)$me['id']):?><form method="post" class="bid-form winner"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="winner_checkout"><b>Congratulations — you won this auction.</b><textarea name="address" required placeholder="Delivery address"></textarea><select name="payment_method"><option value="cod">Cash on Delivery</option><option value="bank_transfer">Bank Transfer</option><option value="advance">Advance Payment</option></select><button class="mp550-btn wide">Checkout winning auction</button></form><?php else:?><div class="auction-ended"><b><?=e(ucfirst(str_replace('_',' ',$a['status'])))?></b><span><?=isset($a['winning_bid'])&&$a['winning_bid']!==null?'Winning price '.mp550_money((float)$a['winning_bid']):'This auction is not accepting bids.'?></span></div><?php endif;?><?php if($me):?><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="watch"><button class="watch-btn">♡ Watch auction</button></form><?php endif;?></div></section><section class="mp550-section auction-info"><div class="panel"><h2>About this item</h2><p><?=nl2br(e((string)$a['description']))?></p></div><aside class="panel"><h2>Bid activity</h2><?php foreach($a['events'] as $e):?><div class="bid-event"><i><?=e(strtoupper(mb_substr((string)($e['user_name']?:'B'),0,1)))?></i><span><b><?=e($e['event_type']==='bid'?'Bid placed':ucfirst($e['event_type']))?></b><small><?=e(date('d M · h:i:s A',strtotime($e['created_at'])))?></small></span><?php if($e['amount']!==null):?><strong><?=mp550_money((float)$e['amount'])?></strong><?php endif;?></div><?php endforeach;?></aside></section>
<?php mp550_public_footer(); ?>
